import{_ as o,o as t,c as r,a0 as i}from"./chunks/framework.ChlVJx0I.js";const w=JSON.parse('{"title":"Context window cap via provider re-registration","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-context-window-cap-via-provider-reregistration.md","filePath":"adr/0004-context-window-cap-via-provider-reregistration.md","lastUpdated":1789309498000}'),a={name:"adr/0004-context-window-cap-via-provider-reregistration.md"};function d(n,e,s,c,p,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="context-window-cap-via-provider-re-registration" tabindex="-1">Context window cap via provider re-registration <a class="header-anchor" href="#context-window-cap-via-provider-re-registration" aria-label="Permalink to &quot;Context window cap via provider re-registration&quot;">​</a></h1><p>The <code>context-cap</code> extension limits a session&#39;s effective context window so auto-compaction fires early. pi has no cap concept; the only source of truth is <code>model.contextWindow</code> on the model object the session resolves. We apply the cap by re-registering each provider&#39;s model list (with capped <code>contextWindow</code>) through the extension <code>registerProvider</code> API, instead of hooking <code>session_start</code>/<code>model_select</code> and calling <code>setModel</code> with a capped copy.</p><p>The hook path was rejected because <code>setModel</code> appends a <code>model_change</code> entry to the session transcript on every call (polluting every session start and switch) and because the <code>/model</code> picker would keep showing the true window while compaction acted on the capped one. The registry path makes the capped window the value pi resolves everywhere: initial model, resume, model switches, picker, footer. The composer keeps base auth, streaming, and model refresh for re-registered providers, so no provider behavior changes except the window.</p><p>Cost accepted: the extension copies every model field at load and must keep that copy complete when pi&#39;s model shape grows.</p>',4)])])}const v=o(a,[["render",d]]);export{w as __pageData,v as default};
